/**
 * Swiper 4.5.1
 * Most modern mobile touch slider and framework with hardware accelerated transitions
 */
function Swiper(el, options) {
    var self = this;
    self.el = el;
    self.options = options || {};
    self.init();
}

Swiper.prototype.init = function() {
    var self = this;
    self.slides = Array.from(self.el.querySelectorAll('.swiper-slide'));
    self.wrapper = self.el.querySelector('.swiper-wrapper');
    self.activeIndex = 0;
    
    if (self.options.autoplay) {
        self.startAutoplay();
    }
    
    if (self.options.navigation) {
        self.initNavigation();
    }
};

Swiper.prototype.startAutoplay = function() {
    var self = this;
    var delay = self.options.autoplay.delay || 3000;
    self.autoplayTimer = setInterval(function() {
        self.slideNext();
    }, delay);
};

Swiper.prototype.stopAutoplay = function() {
    var self = this;
    if (self.autoplayTimer) {
        clearInterval(self.autoplayTimer);
    }
};

Swiper.prototype.slideNext = function() {
    var self = this;
    var nextIndex = (self.activeIndex + 1) % self.slides.length;
    self.slideTo(nextIndex);
};

Swiper.prototype.slidePrev = function() {
    var self = this;
    var prevIndex = (self.activeIndex - 1 + self.slides.length) % self.slides.length;
    self.slideTo(prevIndex);
};

Swiper.prototype.slideTo = function(index) {
    var self = this;
    self.activeIndex = index;
    var slideWidth = self.slides[0].offsetWidth;
    var spaceBetween = self.options.spaceBetween || 0;
    var translate = -(index * (slideWidth + spaceBetween));
    self.wrapper.style.transform = 'translate3d(' + translate + 'px, 0, 0)';
};

Swiper.prototype.initNavigation = function() {
    var self = this;
    var nextEl = document.querySelector(self.options.navigation.nextEl);
    var prevEl = document.querySelector(self.options.navigation.prevEl);
    
    if (nextEl) {
        nextEl.addEventListener('click', function() {
            self.slideNext();
        });
    }
    
    if (prevEl) {
        prevEl.addEventListener('click', function() {
            self.slidePrev();
        });
    }
};

window.Swiper = Swiper;